        .eq('username', nick.trim())
        .eq('password_hash', password)
        .single();

      if (error || !data) {
        alert("Acesso Negado: Credenciais de jogo incorretas.");
      } else {
        onLoginSuccess({
          nick: data.username,
          uuid: data.uuid,
          balance: parseFloat(data.balance || '0'),
          creditLimit: 0,
          currentInvoice: 0
        }, rememberMe);
      }
    } catch (error) {
      alert("Erro de conexão com o banco de dados do servidor.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col items-center justify-center bg-white px-6 py-10 page-enter min-h-screen">
