        <h1 className="text-3xl font-bold tracking-tight text-[#1A1A1A]">
          Painel <span style={{ color: primaryColor }}>RedeWhite</span>
        </h1>
        <p className="text-gray-400 font-semibold text-xs mt-2 mb-10 tracking-widest uppercase italic">Comunidade Gamer</p>

        <form onSubmit={handleLogin} className="w-full flex flex-col gap-4">
