          <div className="flex flex-col gap-1.5">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-1">PIN de Acesso (/banco)</label>
            <input 
              type="password" 
              placeholder="Seu código secreto" 
              className="w-full p-4 bg-[#F5F6F7] border-2 border-transparent rounded-2xl text-[#1A1A1A] font-bold focus:border-[#72E8F6] focus:bg-white transition-all outline-none"
              value={password} 
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-2 ml-1 mt-1">
