import React, { useState, useEffect } from 'react';
import { PlayerData } from '../types';
import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = 'https://mmmazuwqcssymohcdzyj.supabase.co';
const SUPABASE_KEY = 'sb_publishable_bf0YEm9kQ92T5U9WFbKeeg_clS4zyLc';
const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

interface PixAreaProps {
  onBack: () => void;
  player: PlayerData;
}

type PixStep = 'HOME' | 'INPUT_NICK' | 'INPUT_AMOUNT' | 'CONFIRM' | 'SUCCESS';

const PixArea: React.FC<PixAreaProps> = ({ onBack, player }) => {
  const primaryColor = '#72E8F6';
  const [step, setStep] = useState<PixStep>('HOME');
  const [receiverNick, setReceiverNick] = useState('');
  const [amount, setAmount] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [receiverData, setReceiverData] = useState<{ nick: string; uuid: string } | null>(null);

  const resetFlow = () => {
    setStep('HOME');
    setReceiverNick('');
    setAmount('');
    setErrorMessage('');
    setReceiverData(null);
  };

  const handleNextToAmount = async () => {
    if (!receiverNick.trim()) return;
    setIsLoading(true);
    setErrorMessage('');

    try {
      const { data, error } = await supabase
        .from('rede_white_accounts')
        .select('username, uuid')
        .eq('username', receiverNick.trim())
        .single();

      if (error || !data) {
        setErrorMessage('Jogador não encontrado no servidor.');
      } else if (data.username === player.nick) {
        setErrorMessage('Você não pode transferir para si mesmo.');
      } else {
        setReceiverData({ nick: data.username, uuid: data.uuid });
        setStep('INPUT_AMOUNT');
      }
    } catch (e) {
      setErrorMessage('Erro ao verificar jogador.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleConfirmTransfer = async () => {
    const val = parseFloat(amount.replace(',', '.'));
    if (isNaN(val) || val <= 0) return;

    setIsLoading(true);
    try {
      // Record in the transaction queue
      const { error } = await supabase
        .from('rede_white_transactions')
        .insert([{
          sender_name: player.nick,
          receiver_name: receiverData?.nick,
          amount: val,
          status: 'PENDENTE'
        }]);

      if (error) throw error;
      setStep('SUCCESS');
    } catch (e) {
      setErrorMessage('Erro ao processar transferência.');
    } finally {
      setIsLoading(false);
    }
  };

  // Real-time validation for the amount
  useEffect(() => {
    if (step === 'INPUT_AMOUNT' && amount) {
      const val = parseFloat(amount.replace(',', '.'));
      if (val > player.balance) {
        setErrorMessage('Saldo insuficiente para realizar esta operação');
      } else {
        setErrorMessage('');
      }
    }
  }, [amount, step, player.balance]);

  if (step === 'SUCCESS') {
    return (
      <div className="flex-1 flex flex-col bg-white page-enter items-center p-6 text-center">
        <div className="w-full max-w-sm mt-12 mb-8">
          <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mx-auto mb-6">
            <span className="material-icons-outlined text-4xl text-[#2ECC71]">check_circle</span>
          </div>
          <h1 className="text-3xl font-bold text-[#1A1A1A]">Transferência realizada!</h1>
          <p className="text-gray-400 mt-2 font-medium">O valor já está a caminho de {receiverData?.nick}</p>
        </div>

        {/* Receipt Layout */}
        <div id="receipt" className="w-full max-w-sm bg-[#F5F6F7] rounded-[32px] p-8 text-left border border-[#EDEDED] shadow-sm mb-8">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-8 h-8 rounded-lg overflow-hidden border border-gray-200">
               <img src="https://i.imgur.com/bPt3G5b.jpeg" alt="Logo" className="w-full h-full object-cover" />
            </div>
            <span className="text-sm font-bold opacity-30">COMPROVANTE WHITEBANK</span>
          </div>

          <div className="space-y-6">
            <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Valor</p>
              <p className="text-2xl font-bold text-[#1A1A1A]">$ {parseFloat(amount).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
            </div>

            <div className="h-[1px] bg-gray-200 w-full"></div>

            <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Para</p>
              <p className="font-bold text-[#1A1A1A] text-lg">{receiverData?.nick}</p>
              <p className="text-xs text-gray-500 font-medium mt-1">Instituição: Banco RedeWhite</p>
              <p className="text-xs text-gray-500 font-medium">Tipo: Pix</p>
            </div>

            <div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Origem</p>
              <p className="font-bold text-[#1A1A1A]">{player.nick}</p>
              <p className="text-xs text-gray-500 font-medium mt-0.5">ID: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
