import React, { useState, useEffect, useRef } from 'react';
import { PlayerData } from '../types';
import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = 'https://mmmazuwqcssymohcdzyj.supabase.co';
const SUPABASE_KEY = 'sb_publishable_bf0YEm9kQ92T5U9WFbKeeg_clS4zyLc';
const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

interface PixAreaProps {
  onBack: () => void;
  player: PlayerData;
}

type PixStep = 'HOME' | 'INPUT_NICK' | 'INPUT_AMOUNT' | 'CONFIRM' | 'PROCESSING' | 'SUCCESS';

const PixArea: React.FC<PixAreaProps> = ({ onBack, player }) => {
  const primaryColor = '#72E8F6';
  const [step, setStep] = useState<PixStep>('HOME');
  const [receiverNick, setReceiverNick] = useState('');
  const [amount, setAmount] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [receiverData, setReceiverData] = useState<{ nick: string; uuid: string } | null>(null);
  const [transactionId, setTransactionId] = useState('');

  const resetFlow = () => {
    setStep('HOME');
    setReceiverNick('');
    setAmount('');
    setErrorMessage('');
    setReceiverData(null);
    setTransactionId('');
  };

  const handleNextToAmount = async () => {
    if (!receiverNick.trim()) return;
    setIsLoading(true);
    setErrorMessage('');

    try {
      const { data, error } = await supabase
        .from('rede_white_accounts')
        .select('username, uuid')
        .eq('username', receiverNick.trim())
        .single();

      if (error || !data) {
        setErrorMessage('Jogador não encontrado no servidor.');
      } else if (data.username.toLowerCase() === player.nick.toLowerCase()) {
        setErrorMessage('Você não pode transferir para si mesmo.');
      } else {
        setReceiverData({ nick: data.username, uuid: data.uuid });
        setStep('INPUT_AMOUNT');
      }
    } catch (e) {
      setErrorMessage('Erro ao verificar jogador.');
    } finally {
      setIsLoading(false);
    }
  };

  const startProcessing = async () => {
    setStep('PROCESSING');
    setIsLoading(true);
    setErrorMessage('');

    const val = parseFloat(amount.replace(',', '.'));

    // Simulação de processamento bancário seguro
    setTimeout(async () => {
      try {
        // Validação de segurança final no servidor (Supabase)
        const { data: accountData, error: accountError } = await supabase
          .from('rede_white_accounts')
          .select('balance')
          .eq('username', player.nick)
          .single();

        if (accountError || !accountData) throw new Error('Falha crítica de conexão.');

        const currentBalance = parseFloat(accountData.balance || '0');
        if (currentBalance < val) {
          setErrorMessage('Saldo insuficiente confirmado pelo servidor.');
          setStep('INPUT_AMOUNT');
          setIsLoading(false);
          return;
        }

        // Registro da transação na fila oficial
        const newId = Math.random().toString(36).substr(2, 9).toUpperCase();
        const { error: txError } = await supabase
          .from('rede_white_transactions')
          .insert([{
            sender_name: player.nick,
            receiver_name: receiverData?.nick,
            amount: val,
            status: 'PENDENTE'
          }]);

        if (txError) throw txError;

        setTransactionId(newId);
        setStep('SUCCESS');
      } catch (e) {
        setErrorMessage('Erro no sistema de pagamentos. Tente novamente.');
        setStep('CONFIRM');
      } finally {
        setIsLoading(false);
      }
    }, 2800);
  };

  // Monitor de validação de campo
  useEffect(() => {
    if (step === 'INPUT_AMOUNT' && amount) {
      const val = parseFloat(amount.replace(',', '.'));
      if (val > player.balance) {
        setErrorMessage('Saldo insuficiente para realizar esta operação');
      } else if (val <= 0) {
        setErrorMessage('Insira um valor maior que zero');
      } else {
        setErrorMessage('');
      }
    }
  }, [amount, step, player.balance]);

  // UI: Botão de Ação Inferior (Padrão Responsivo)
  const ActionButton = ({ onClick, disabled, label, loading = false, variant = 'primary' }: any) => (
    <div className="fixed bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-white via-white/90 to-transparent z-50 md:relative md:bg-none md:p-0 md:mt-8">
      <button 
        disabled={disabled || loading}
        onClick={onClick}
        className={`w-full py-5 rounded-2xl font-bold transition-all active:scale-95 flex items-center justify-center gap-2 shadow-lg shadow-cyan-500/10 h-16 text-lg ${
          variant === 'primary' 
          ? 'text-white' 
          : 'bg-gray-100 text-gray-500 shadow-none'
        } disabled:opacity-30`}
        style={variant === 'primary' ? { backgroundColor: primaryColor } : {}}
      >
        {loading ? (
          <div className="w-6 h-6 border-3 border-white border-t-transparent rounded-full animate-spin"></div>
        ) : label}
      </button>
    </div>
  );

  // VIEW: Processando
  if (step === 'PROCESSING') {
    return (
      <div className="flex-1 flex flex-col items-center justify-center bg-white h-screen p-8 text-center page-enter">
