          </div>
          <h1 className="text-3xl font-bold text-gray-900 text-center leading-tight">Transferência realizada!</h1>
          <p className="text-gray-400 mt-2 text-center font-medium">O valor já está disponível para {receiverData?.nick}</p>
        </div>

        {/* Comprovante Digital */}
        <div className="px-6 mt-10">
          <div id="receipt-printable" className="bg-[#F5F6F7] rounded-[32px] p-8 border border-gray-100">
            <div className="flex items-center gap-3 mb-10">
              <img src="https://i.imgur.com/bPt3G5b.jpeg" className="w-6 h-6 rounded" alt="Logo" />
              <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">COMPROVANTE WHITEBANK</span>
            </div>

            <div className="space-y-8">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">VALOR</p>
                <p className="text-4xl font-bold text-gray-900">$ {parseFloat(amount).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>

              <div className="h-[1px] bg-gray-200"></div>

              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">PARA</p>
                <p className="text-xl font-bold text-gray-900">{receiverData?.nick}</p>
                <div className="flex gap-2 mt-2">
                  <span className="text-[9px] font-bold text-gray-400 bg-white px-2 py-1 rounded-md border border-gray-100">BANCO REDEWHITE</span>
                  <span className="text-[9px] font-bold text-gray-400 bg-white px-2 py-1 rounded-md border border-gray-100">PIX</span>
                </div>
              </div>

              <div>
