          >
            <span className="material-icons-outlined">file_download</span>
            Baixar Comprovante
          </button>
          <button 
            onClick={resetFlow}
            className="w-full py-4 text-gray-400 font-bold hover:text-gray-600 transition-colors"
          >
            Voltar ao Início
          </button>
        </div>
      </div>
    );
  }

  // HEADER COMUM PARA TODOS OS PASSOS
  const StepHeader = ({ title, subtitle, onBackAction }: any) => (
    <header className="px-6 pt-12 pb-6 sticky top-0 bg-white z-40">
      <button onClick={onBackAction} className="p-2 -ml-2 rounded-full hover:bg-gray-50 mb-6">
