  // PASSO 2: VALOR
  if (step === 'INPUT_AMOUNT') {
    return (
      <div className="flex-1 flex flex-col bg-white h-full relative page-enter">
        <header className="px-6 pt-12 pb-6">
          <button onClick={() => setStep('INPUT_NICK')} className="p-2 -ml-2 rounded-full hover:bg-gray-50 mb-6">
