                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Para</p>
                 <p className="text-lg font-bold text-gray-900">{receiverData?.nick}</p>
               </div>
               <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center text-gray-400">
                 <span className="material-icons-outlined text-xl">person</span>
               </div>
             </div>

             <div className="grid grid-cols-2 gap-3">
               <div className="bg-[#F5F6F7] p-4 rounded-xl">
                 <p className="text-[9px] font-bold text-gray-400 uppercase mb-1">Banco</p>
                 <p className="text-[11px] font-bold text-gray-700">RedeWhite</p>
               </div>
               <div className="bg-[#F5F6F7] p-4 rounded-xl">
                 <p className="text-[9px] font-bold text-gray-400 uppercase mb-1">Tipo</p>
                 <p className="text-[11px] font-bold text-gray-700">Pix Digital</p>
               </div>
             </div>
          </div>
        </div>
      </StepLayout>
    );
  }

  // HOME ÁREA PIX
  return (
    <div className="flex flex-col bg-white h-screen page-enter overflow-hidden pb-24 md:pb-0">
      <header className="bg-white pt-12 pb-6 px-6 border-b border-gray-100 z-10 sticky top-0 flex-shrink-0">
        <div className="flex justify-between items-center mb-6">
          <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-gray-50 text-cyan-400 transition-colors">
            <span className="material-icons-outlined">chevron_left</span>
          </button>
          <div className="flex gap-4 text-gray-400">
            <span className="material-icons-outlined cursor-pointer text-xl">help_outline</span>
            <span className="material-icons-outlined cursor-pointer text-xl">settings</span>
          </div>
        </div>
        <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Área Pix</h1>
        <p className="text-gray-400 text-xs font-medium mt-1">Transfira coins instantaneamente.</p>
      </header>

      <div className="flex-1 overflow-y-auto hide-scrollbar p-6 space-y-8">
        <section>
          <h2 className="text-sm font-bold text-gray-900 mb-6 uppercase tracking-widest opacity-50">Enviar</h2>
          <div className="grid grid-cols-1 gap-3">
            <button 
              onClick={() => setStep('INPUT_NICK')}
              className="flex items-center p-4 bg-[#F5F6F7] rounded-[24px] active:scale-[0.98] transition-all group"
            >
              <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center mr-4 shadow-sm group-hover:shadow-md transition-shadow">
                <span className="material-icons-outlined text-cyan-400 text-xl">payments</span>
              </div>
              <div className="text-left flex-1">
                <p className="font-bold text-gray-900 text-sm">Transferir</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Mande coins via Nick</p>
              </div>
              <span className="material-icons-outlined text-gray-200 text-lg">chevron_right</span>
            </button>
          </div>
        </section>

        <section className="pt-6 border-t border-gray-50">
          <h2 className="text-sm font-bold text-gray-900 mb-4 uppercase tracking-widest opacity-50">Minha chave</h2>
          <div className="bg-white border border-gray-100 rounded-[24px] p-5 flex justify-between items-center shadow-sm">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-cyan-50 rounded-full flex items-center justify-center text-cyan-400">
                <span className="material-icons-outlined text-lg">person</span>
              </div>
              <div>
                <p className="text-[8px] font-black text-cyan-400 uppercase tracking-widest mb-0.5">NICK ATUAL</p>
                <p className="font-bold text-gray-900 text-base">{player.nick}</p>
              </div>
            </div>
            <button className="p-2.5 bg-gray-50 rounded-full text-cyan-400 active:bg-cyan-100 transition-colors">
              <span className="material-icons-outlined text-lg">content_copy</span>
            </button>
          </div>
        </section>
      </div>
    </div>
  );
};

export default PixArea;

payload.text:
"use client"

import React, { useState, useEffect } from "react"
import { createClient } from "@supabase/supabase-js"
import { ArrowLeft, X, User, Send, Copy, Check, Loader2, ChevronRight, Download, AlertCircle } from "lucide-react"
import { cn } from "@/lib/utils"

const SUPABASE_URL = "https://mmmazuwqcssymohcdzyj.supabase.co"
const SUPABASE_KEY = "sb_publishable_bf0YEm9kQ92T5U9WFbKeeg_clS4zyLc"
const supabase = createClient(SUPABASE_URL, SUPABASE_KEY)

interface PlayerData {
  nick: string
  balance: number
  uuid?: string
}

interface PixAreaProps {
  onBack: () => void
  player: PlayerData
}

type PixStep = "HOME" | "INPUT_NICK" | "INPUT_AMOUNT" | "CONFIRM" | "PROCESSING" | "SUCCESS"

export default function PixArea({ onBack, player }: PixAreaProps) {
  const [step, setStep] = useState<PixStep>("HOME")
  const [receiverNick, setReceiverNick] = useState("")
  const [amount, setAmount] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")
  const [receiverData, setReceiverData] = useState<{ nick: string; uuid: string } | null>(null)
  const [transactionId, setTransactionId] = useState("")
  const [copied, setCopied] = useState(false)

  const resetFlow = () => {
    setStep("HOME")
    setReceiverNick("")
    setAmount("")
    setErrorMessage("")
    setReceiverData(null)
    setTransactionId("")
  }

  const handleNextToAmount = async () => {
    if (!receiverNick.trim()) return
    setIsLoading(true)
    setErrorMessage("")

    try {
      const { data, error } = await supabase
        .from("rede_white_accounts")
        .select("username, uuid")
        .ilike("username", receiverNick.trim())
        .single()

      if (error || !data) {
        setErrorMessage("Jogador nao encontrado no servidor.")
      } else if (data.username.toLowerCase() === player.nick.toLowerCase()) {
        setErrorMessage("Voce nao pode transferir para si mesmo.")
      } else {
        setReceiverData({ nick: data.username, uuid: data.uuid })
        setStep("INPUT_AMOUNT")
      }
    } catch {
      setErrorMessage("Erro ao verificar jogador.")
    } finally {
      setIsLoading(false)
    }
  }

  const startProcessing = async () => {
    setStep("PROCESSING")
    setIsLoading(true)
    setErrorMessage("")

    const val = parseFloat(amount.replace(",", "."))

    setTimeout(async () => {
      try {
        const { data: accountData, error: accountError } = await supabase
          .from("rede_white_accounts")
          .select("balance")
          .eq("username", player.nick)
          .single()

        if (accountError || !accountData) throw new Error("Falha de conexao.")

        const currentBalance = parseFloat(accountData.balance || "0")
        if (currentBalance < val) {
          setErrorMessage("Saldo insuficiente confirmado pelo servidor.")
          setStep("INPUT_AMOUNT")
          setIsLoading(false)
          return
        }

        const newId = Math.random().toString(36).substr(2, 9).toUpperCase()
        const { error: txError } = await supabase.from("rede_white_transactions").insert([
          {
            sender_name: player.nick,
            receiver_name: receiverData?.nick,
            amount: val,
            status: "PENDENTE",
          },
        ])

        if (txError) throw txError

        setTransactionId(newId)
        setStep("SUCCESS")
      } catch {
        setErrorMessage("Erro no sistema de pagamentos. Tente novamente.")
        setStep("CONFIRM")
      } finally {
        setIsLoading(false)
      }
    }, 2500)
  }

  useEffect(() => {
    if (step === "INPUT_AMOUNT" && amount) {
      const val = parseFloat(amount.replace(",", "."))
      if (isNaN(val) || val <= 0) {
        setErrorMessage("Digite um valor valido maior que zero")
      } else if (val > player.balance) {
        setErrorMessage("Saldo insuficiente para esta operacao")
      } else {
        setErrorMessage("")
      }
    } else if (step === "INPUT_AMOUNT") {
      setErrorMessage("")
    }
  }, [amount, step, player.balance])

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const formatCurrency = (value: number) => {
    return value.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  }

  const parsedAmount = parseFloat(amount.replace(",", ".")) || 0

  // PROCESSING VIEW
  if (step === "PROCESSING") {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center bg-white px-6">
        <div className="relative mb-8">
          <div className="h-20 w-20 rounded-full border-4 border-cyan-100" />
          <div className="absolute inset-0 h-20 w-20 animate-spin rounded-full border-4 border-transparent border-t-cyan-500" />
        </div>
        <h2 className="mb-2 text-xl font-bold text-gray-900">Processando transferencia</h2>
        <p className="text-center text-sm text-gray-500">
          Verificando saldo e seguranca da transacao...
        </p>
      </div>
    )
  }

  // SUCCESS VIEW
  if (step === "SUCCESS") {
    return (
      <div className="flex min-h-screen flex-col bg-white">
        <div className="flex flex-1 flex-col items-center px-6 pt-16">
          <div className="mb-6 flex h-20 w-20 items-center justify-center rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/30">
            <Check className="h-10 w-10 text-white" strokeWidth={3} />
          </div>
          <h1 className="mb-2 text-2xl font-bold text-gray-900">Transferencia enviada!</h1>
          <p className="mb-10 text-center text-sm text-gray-500">
            O valor ja esta disponivel na conta de <span className="font-semibold">{receiverData?.nick}</span>
          </p>

          {/* Receipt */}
          <div className="w-full max-w-sm rounded-3xl bg-gray-50 p-6">
            <div className="mb-6 flex items-center gap-2">
              <div className="flex h-6 w-6 items-center justify-center rounded bg-cyan-500 text-xs font-bold text-white">
                W
              </div>
              <span className="text-xs font-bold uppercase tracking-widest text-gray-400">
                Comprovante
              </span>
            </div>

            <div className="mb-6">
              <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">Valor</p>
              <p className="text-3xl font-bold text-gray-900">W$ {formatCurrency(parsedAmount)}</p>
            </div>

            <div className="mb-6 h-px bg-gray-200" />

            <div className="space-y-5">
              <div>
                <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">Para</p>
                <p className="text-lg font-bold text-gray-900">{receiverData?.nick}</p>
                <p className="text-xs text-gray-400">Banco RedeWhite</p>
              </div>
              <div>
                <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">De</p>
                <p className="font-semibold text-gray-900">{player.nick}</p>
                <p className="font-mono text-xs text-gray-400">ID: {transactionId}</p>
              </div>
            </div>

            <div className="mt-6 flex items-center justify-between border-t border-dashed border-gray-200 pt-4 text-xs text-gray-400">
              <span>{new Date().toLocaleDateString("pt-BR")}</span>
              <span>{new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span>
            </div>
          </div>
        </div>

        {/* Footer Buttons */}
        <div className="sticky bottom-0 space-y-3 bg-white p-6">
          <button
            onClick={() => window.print()}
            className="flex h-14 w-full items-center justify-center gap-2 rounded-2xl bg-cyan-500 font-bold text-white shadow-lg shadow-cyan-500/20 transition-all active:scale-[0.98]"
          >
            <Download className="h-5 w-5" />
            Baixar Comprovante
          </button>
          <button
            onClick={resetFlow}
            className="h-12 w-full text-sm font-semibold text-gray-500 transition-colors hover:text-gray-700"
          >
            Voltar ao inicio
          </button>
        </div>
      </div>
    )
  }

  // INPUT NICK VIEW
  if (step === "INPUT_NICK") {
    return (
      <div className="flex min-h-screen flex-col bg-white">
        <header className="flex-shrink-0 px-6 pb-4 pt-12">
          <button
            onClick={() => setStep("HOME")}
            className="-ml-2 mb-6 flex h-10 w-10 items-center justify-center rounded-full text-gray-600 transition-colors hover:bg-gray-100"
          >
            <X className="h-6 w-6" />
          </button>
          <h1 className="text-2xl font-bold text-gray-900">Para quem voce quer transferir?</h1>
          <p className="mt-1 text-sm text-gray-500">Digite o nickname do jogador</p>
        </header>

        <main className="flex-1 px-6">
          <div className="mt-4">
            <input
              autoFocus
              type="text"
              placeholder="NICKNAME"
              className="w-full border-b-2 border-gray-200 bg-transparent py-4 text-2xl font-bold uppercase text-gray-900 placeholder:text-gray-300 focus:border-cyan-500 focus:outline-none"
              value={receiverNick}
              onChange={(e) => setReceiverNick(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleNextToAmount()}
            />
          </div>

          {errorMessage && (
            <div className="mt-6 flex items-center gap-3 rounded-2xl bg-red-50 p-4">
              <AlertCircle className="h-5 w-5 flex-shrink-0 text-red-500" />
              <p className="text-sm font-medium text-red-600">{errorMessage}</p>
            </div>
          )}
        </main>

        <div className="sticky bottom-0 bg-white p-6">
          <button
            disabled={!receiverNick.trim() || isLoading}
            onClick={handleNextToAmount}
            className={cn(
              "flex h-14 w-full items-center justify-center rounded-2xl font-bold transition-all active:scale-[0.98]",
              receiverNick.trim() && !isLoading
                ? "bg-cyan-500 text-white shadow-lg shadow-cyan-500/20"
                : "bg-gray-100 text-gray-400"
            )}
          >
            {isLoading ? <Loader2 className="h-6 w-6 animate-spin" /> : "Continuar"}
          </button>
        </div>
      </div>
    )
  }

  // INPUT AMOUNT VIEW
  if (step === "INPUT_AMOUNT") {
    const isValidAmount = parsedAmount > 0 && parsedAmount <= player.balance

    return (
      <div className="flex min-h-screen flex-col bg-white">
        <header className="flex-shrink-0 px-6 pb-4 pt-12">
          <button
            onClick={() => setStep("INPUT_NICK")}
            className="-ml-2 mb-6 flex h-10 w-10 items-center justify-center rounded-full text-gray-600 transition-colors hover:bg-gray-100"
          >
            <ArrowLeft className="h-6 w-6" />
          </button>
          <h1 className="text-2xl font-bold text-gray-900">Qual o valor?</h1>
          <div className="mt-3 flex items-center gap-2">
            <span className="text-sm text-gray-500">Saldo disponivel:</span>
            <span className="text-sm font-bold text-emerald-600">W$ {formatCurrency(player.balance)}</span>
          </div>
        </header>

        <main className="flex-1 px-6">
          <div className="mt-6 flex items-baseline gap-2 border-b-2 border-gray-200 pb-4 focus-within:border-cyan-500">
            <span className="text-4xl font-bold text-gray-300">W$</span>
            <input
              autoFocus
              type="text"
              inputMode="decimal"
              placeholder="0,00"
              className="w-full bg-transparent text-4xl font-bold text-gray-900 placeholder:text-gray-300 focus:outline-none"
              value={amount}
              onChange={(e) => {
                const value = e.target.value.replace(/[^0-9,\.]/g, "")
                setAmount(value)
              }}
            />
          </div>

          {/* Quick amount buttons */}
          <div className="mt-6 flex gap-2">
            {[100, 500, 1000].map((val) => (
              <button
                key={val}
                onClick={() => setAmount(val.toString())}
                disabled={val > player.balance}
                className={cn(
                  "flex-1 rounded-xl py-3 text-sm font-semibold transition-colors",
                  val <= player.balance
                    ? "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    : "bg-gray-50 text-gray-300"
                )}
              >
                W$ {val}
              </button>
            ))}
          </div>

          {errorMessage && (
            <div className="mt-6 flex items-center gap-3 rounded-2xl bg-red-50 p-4">
              <AlertCircle className="h-5 w-5 flex-shrink-0 text-red-500" />
              <p className="text-sm font-medium text-red-600">{errorMessage}</p>
            </div>
          )}

          {/* Receiver info */}
          <div className="mt-8 flex items-center gap-4 rounded-2xl bg-gray-50 p-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-cyan-100 text-cyan-600">
              <User className="h-6 w-6" />
            </div>
            <div>
              <p className="text-xs font-semibold uppercase tracking-wide text-gray-400">Enviando para</p>
              <p className="text-lg font-bold text-gray-900">{receiverData?.nick}</p>
            </div>
          </div>
        </main>

        <div className="sticky bottom-0 bg-white p-6">
          <button
            disabled={!isValidAmount}
            onClick={() => setStep("CONFIRM")}
            className={cn(
              "flex h-14 w-full items-center justify-center rounded-2xl font-bold transition-all active:scale-[0.98]",
              isValidAmount
                ? "bg-cyan-500 text-white shadow-lg shadow-cyan-500/20"
                : "bg-gray-100 text-gray-400"
            )}
          >
            Revisar transferencia
          </button>
        </div>
      </div>
    )
  }

  // CONFIRM VIEW
  if (step === "CONFIRM") {
    return (
      <div className="flex min-h-screen flex-col bg-white">
        <header className="flex-shrink-0 px-6 pb-4 pt-12">
          <button
            onClick={() => setStep("INPUT_AMOUNT")}
            className="-ml-2 mb-6 flex h-10 w-10 items-center justify-center rounded-full text-gray-600 transition-colors hover:bg-gray-100"
          >
            <ArrowLeft className="h-6 w-6" />
          </button>
          <h1 className="text-2xl font-bold text-gray-900">Confira os dados</h1>
          <p className="mt-1 text-sm text-gray-500">Verifique se esta tudo certo</p>
        </header>

        <main className="flex-1 px-6">
          {/* Amount card */}
          <div className="mt-4 rounded-3xl bg-cyan-500 p-6 text-white shadow-lg shadow-cyan-500/20">
            <p className="mb-1 text-sm font-medium text-cyan-100">Valor a enviar</p>
            <p className="text-4xl font-bold">W$ {formatCurrency(parsedAmount)}</p>
          </div>

          {/* Details */}
          <div className="mt-8 space-y-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gray-100 text-gray-600">
                  <User className="h-6 w-6" />
                </div>
                <div>
                  <p className="text-xs font-semibold uppercase tracking-wide text-gray-400">Para</p>
                  <p className="text-lg font-bold text-gray-900">{receiverData?.nick}</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="rounded-2xl bg-gray-50 p-4">
                <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">Banco</p>
                <p className="font-bold text-gray-900">RedeWhite</p>
              </div>
              <div className="rounded-2xl bg-gray-50 p-4">
                <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">Tipo</p>
                <p className="font-bold text-gray-900">Pix Digital</p>
              </div>
            </div>

            <div className="rounded-2xl bg-gray-50 p-4">
              <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-gray-400">De</p>
              <p className="font-bold text-gray-900">{player.nick}</p>
              <p className="mt-1 text-xs text-gray-400">
                Saldo apos a transferencia: W$ {formatCurrency(player.balance - parsedAmount)}
              </p>
            </div>
          </div>

          {errorMessage && (
            <div className="mt-6 flex items-center gap-3 rounded-2xl bg-red-50 p-4">
              <AlertCircle className="h-5 w-5 flex-shrink-0 text-red-500" />
              <p className="text-sm font-medium text-red-600">{errorMessage}</p>
            </div>
          )}
        </main>

        <div className="sticky bottom-0 bg-white p-6">
          <button
            onClick={startProcessing}
            className="flex h-14 w-full items-center justify-center gap-2 rounded-2xl bg-cyan-500 font-bold text-white shadow-lg shadow-cyan-500/20 transition-all active:scale-[0.98]"
          >
            <Send className="h-5 w-5" />
            Confirmar e Enviar
          </button>
        </div>
      </div>
    )
  }

  // HOME VIEW
  return (
    <div className="flex min-h-screen flex-col bg-white">
      <header className="flex-shrink-0 border-b border-gray-100 bg-white px-6 pb-6 pt-12">
        <div className="mb-6 flex items-center justify-between">
          <button
            onClick={onBack}
            className="-ml-2 flex h-10 w-10 items-center justify-center rounded-full text-cyan-500 transition-colors hover:bg-gray-100"
          >
            <ArrowLeft className="h-6 w-6" />
          </button>
        </div>
        <h1 className="text-2xl font-bold text-gray-900">Area Pix</h1>
        <p className="mt-1 text-sm text-gray-500">Transfira coins instantaneamente</p>
      </header>

      <main className="flex-1 overflow-y-auto p-6">
        {/* Transfer section */}
        <section className="mb-8">
          <h2 className="mb-4 text-xs font-bold uppercase tracking-widest text-gray-400">Enviar</h2>
          <button
            onClick={() => setStep("INPUT_NICK")}
            className="flex w-full items-center gap-4 rounded-3xl bg-gray-50 p-4 transition-all hover:bg-gray-100 active:scale-[0.98]"
          >
            <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-white shadow-sm">
              <Send className="h-6 w-6 text-cyan-500" />
            </div>
            <div className="flex-1 text-left">
              <p className="font-bold text-gray-900">Transferir</p>
              <p className="text-xs text-gray-500">Envie coins para outro jogador</p>
            </div>
            <ChevronRight className="h-5 w-5 text-gray-300" />
          </button>
        </section>

        {/* My key section */}
        <section>
          <h2 className="mb-4 text-xs font-bold uppercase tracking-widest text-gray-400">Minha chave Pix</h2>
          <div className="flex items-center justify-between rounded-3xl border border-gray-100 bg-white p-5 shadow-sm">
            <div className="flex items-center gap-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-cyan-50 text-cyan-500">
                <User className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-bold uppercase tracking-widest text-cyan-500">Nickname</p>
                <p className="text-lg font-bold text-gray-900">{player.nick}</p>
              </div>
            </div>
            <button
              onClick={() => copyToClipboard(player.nick)}
              className="flex h-10 w-10 items-center justify-center rounded-full bg-gray-50 text-cyan-500 transition-colors hover:bg-cyan-50"
            >
              {copied ? <Check className="h-5 w-5 text-emerald-500" /> : <Copy className="h-5 w-5" />}
            </button>
          </div>
        </section>

        {/* Balance card */}
        <section className="mt-8">
